#!/bin/bash
# Reference solution (oracle) for mruby-arvo-48877-e2e, generated by conversion/convert.py.
# Writes the upstream fix (projects/mruby/arvo_48877/patch.diff @ 8365b29) to
# /output/fix.patch and the ground-truth PoC to /output/poc.bin.
set -euo pipefail

mkdir -p /output
